// -------- Mobile drawer --------
(function () {
  const ham = document.getElementById('hamburger');
  const drawer = document.getElementById('drawer');
  const close = document.getElementById('drawer-close');
  const backdrop = document.getElementById('mega-backdrop');
  function open() {
    drawer.classList.add('open');
    drawer.setAttribute('aria-hidden', 'false');
    ham.classList.add('open');
    ham.setAttribute('aria-expanded', 'true');
    backdrop.classList.add('open');
    document.body.style.overflow = 'hidden';
  }
  function closeDrawer() {
    drawer.classList.remove('open');
    drawer.setAttribute('aria-hidden', 'true');
    ham.classList.remove('open');
    ham.setAttribute('aria-expanded', 'false');
    backdrop.classList.remove('open');
    document.body.style.overflow = '';
  }
  ham.addEventListener('click', () => {
    if (drawer.classList.contains('open')) closeDrawer();
    else open();
  });
  close.addEventListener('click', closeDrawer);
  backdrop.addEventListener('click', closeDrawer);
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && drawer.classList.contains('open')) closeDrawer();
  });
  // Auto-close on resize-up to desktop
  window.addEventListener('resize', () => {
    if (window.innerWidth >= 981 && drawer.classList.contains('open')) closeDrawer();
  });
})();

// -------- Mega menu --------
(function () {
  const triggers = document.querySelectorAll('.nav-link.has-mega');
  const panels = document.querySelectorAll('.mega');
  const backdrop = document.getElementById('mega-backdrop');
  let openKey = null;
  let closeTimer = null;

  function openMega(key) {
    clearTimeout(closeTimer);
    openKey = key;
    panels.forEach(p => p.classList.toggle('open', p.dataset.panel === key));
    triggers.forEach(t => t.classList.toggle('open', t.dataset.mega === key));
    backdrop.classList.add('open');
  }
  function closeMega() {
    openKey = null;
    panels.forEach(p => p.classList.remove('open'));
    triggers.forEach(t => t.classList.remove('open'));
    backdrop.classList.remove('open');
  }
  function deferredClose() {
    clearTimeout(closeTimer);
    closeTimer = setTimeout(closeMega, 160);
  }

  triggers.forEach(t => {
    t.addEventListener('mouseenter', () => openMega(t.dataset.mega));
    t.addEventListener('mouseleave', deferredClose);
    // Click toggle for touch / keyboard
    t.querySelector('a').addEventListener('click', (e) => {
      e.preventDefault();
      if (openKey === t.dataset.mega) closeMega();
      else openMega(t.dataset.mega);
    });
  });
  panels.forEach(p => {
    p.addEventListener('mouseenter', () => clearTimeout(closeTimer));
    p.addEventListener('mouseleave', deferredClose);
  });
  backdrop.addEventListener('click', closeMega);

  // Close on Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeMega();
  });
  // Close when scrolling away
  let lastY = window.scrollY;
  window.addEventListener('scroll', () => {
    if (Math.abs(window.scrollY - lastY) > 80 && openKey) closeMega();
    lastY = window.scrollY;
  }, { passive: true });
})();

