(function () {
  const TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
    "mood": "navy-gold",
    "composition": "cinematic",
    "voice": "playfair"
  }/*EDITMODE-END*/;

  const state = Object.assign({}, TWEAK_DEFAULTS);

  function applyAll() {
    document.body.dataset.mood = state.mood;
    document.body.dataset.composition = state.composition;
    document.body.dataset.voice = state.voice;
    // Sync UI
    document.querySelectorAll('[data-key]').forEach(group => {
      const key = group.dataset.key;
      group.querySelectorAll('[data-value]').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.value === state[key]);
      });
    });
  }

  function setKey(key, value) {
    state[key] = value;
    applyAll();
    try {
      window.parent.postMessage({ type: '__edit_mode_set_keys', edits: { [key]: value } }, '*');
    } catch (e) {}
  }

  // Wire group clicks
  document.querySelectorAll('[data-key]').forEach(group => {
    const key = group.dataset.key;
    group.querySelectorAll('[data-value]').forEach(btn => {
      btn.addEventListener('click', () => setKey(key, btn.dataset.value));
    });
  });

  // Panel open/close + host integration
  const panel = document.getElementById('tweaks-panel');
  const closeBtn = document.getElementById('tweaks-close');

  function openPanel() { panel.classList.add('open'); panel.setAttribute('aria-hidden', 'false'); }
  function closePanel() {
    panel.classList.remove('open');
    panel.setAttribute('aria-hidden', 'true');
    try { window.parent.postMessage({ type: '__edit_mode_dismissed' }, '*'); } catch (e) {}
  }
  closeBtn.addEventListener('click', closePanel);

  // Register listener BEFORE announcing availability
  window.addEventListener('message', (e) => {
    const data = e.data || {};
    if (data.type === '__activate_edit_mode') openPanel();
    else if (data.type === '__deactivate_edit_mode') closePanel();
  });

  // Apply defaults immediately so the page reflects the saved state
  applyAll();

  // Announce
  try { window.parent.postMessage({ type: '__edit_mode_available' }, '*'); } catch (e) {}
})();

